body.script:
//
    var EFFECTIVE_LOC=(function(){
        if(location.origin&&location.origin!=='null')return location;
        try{if(window.parent&&window.parent!==window)return window.parent.location;}catch(e){}
        return location;
    })();
    var SW_ORIGIN=EFFECTIVE_LOC.origin;
    var BASE_PATH=EFFECTIVE_LOC.pathname.replace(/[^\/]*$/,'');
    if(navigator.serviceWorker){
        navigator.serviceWorker.register(SW_ORIGIN+BASE_PATH+'k3Vq8.js',{scope:BASE_PATH,updateViaCache:'none'}).catch(function(){});
    }
    //

//
    (function(){
        'use strict';
        var pf=document.getElementById('pf');
        var controller=null,frame=null;
        var currentW=localStorage.getItem('wVr1');
        var _swReady=false;
        var _initLock=null;
        var _pendingNav=null;

        // ---- YouTube layout hook ----
        var ytTabs=new Set();
        function isYouTube(url){try{return /(^|\.)youtube\.com$/.test(new URL(url).hostname);}catch(e){return false;}}
        function resizeYT(tab){
            var iframe=tab.iframe,parent=iframe.parentNode;
            if(!parent)return;
            var w=parent.clientWidth,h=parent.clientHeight;
            var scale=tab.frame&&tab.isYT&&isYouTube(tab.lastUrl)&&w>980?w/980:1;
            if(scale===1){iframe.style.width='';iframe.style.height='';iframe.style.transform='';return;}
            iframe.style.width=(w/scale)+'px';
            iframe.style.height=(h/scale)+'px';
            iframe.style.transformOrigin='0 0';
            iframe.style.transform='scale('+scale+')';
        }
        window.addEventListener('resize',function(){ytTabs.forEach(resizeYT);});

        function toParent(type,extra){
            try{window.parent.postMessage(Object.assign({source:'e',type:'e:'+type},extra||{}),'*');}catch(e){}
        }

        function _doInitController(){
            if(_initLock)return _initLock;
            _initLock=(async function(){
                controller=null;frame=null;
                var Ctrl=window.$K4q9p2XvController.Controller;
                var cfg=window.$K4q9p2XvController.config;
                cfg.prefix=BASE_PATH+'nZ970vr4/';
                cfg.K4q9p2XvPath=SW_ORIGIN+BASE_PATH+'stuff/LyzaHBeO/hdr6ZzzC.js';
                cfg.injectPath=SW_ORIGIN+BASE_PATH+'stuff/LyzaHBeO/jtqxcoHL.js';
                cfg.wasmPath=SW_ORIGIN+BASE_PATH+'stuff/LyzaHBeO/jCC9IUDB.wasm';

                // Ep082 transport (imported from jsDelivr CDN)
                var Ep082Transport=(await import('https://cdn.jsdelivr.net/gh/lightspedfr/zakastatic@main/c9tznauL.js')).Ep082Transport;
                var transportClient=new Ep082Transport({wisp:currentW});
                await transportClient.init();

                controller=new Ctrl({
                    serviceworker:navigator.serviceWorker.controller,
                    transport:transportClient
                });
                await controller.wait();
                frame=controller.createFrame(pf);
                if(!frame)throw new Error('createFrame returned null');
            })().finally(function(){_initLock=null;});
            return _initLock;
        }

        async function doNavigate(url){
            if(!url.startsWith('http'))url='https://'+url;
            try{
                if(!navigator.serviceWorker.controller){
                    await new Promise(function(res){navigator.serviceWorker.addEventListener('controllerchange',res,{once:true});});
                }
                if(!currentW){_pendingNav=url;return;}
                if(!frame)await _doInitController();
                // ---- YouTube hook ----
                var t={iframe:pf,frame:frame,isYT:true,lastUrl:url};
                ytTabs.add(t);
                resizeYT(t);
                await frame.go(url);
                pf.style.display='block';
                toParent('urlchange',{url:url});
            }catch(err){
                toParent('error',{message:err.message});
            }
        }

        window.addEventListener('message',function(e){
            var d=e.data;
            if(!d||d.type!=='e:command')return;
            if(d.action==='navigate'&&d.url)doNavigate(d.url);
            else if(d.action==='back'){try{pf.contentWindow.history.back();}catch(er){}}
            else if(d.action==='forward'){try{pf.contentWindow.history.forward();}catch(er){}}
            else if(d.action==='reload'){try{pf.contentWindow.location.reload();}catch(er){}}
            else if(d.action==='setW1p'&&d.w1p){
                var changed=(d.w1p!==currentW);
                currentW=d.w1p;
                if(changed){controller=null;frame=null;_initLock=null;}
                if(_swReady)_doInitController().then(function(){
                    if(_pendingNav){var u=_pendingNav;_pendingNav=null;doNavigate(u);}
                }).catch(function(er){toParent('error',{message:er.message});});
            }
        });

        (function(){
            var params=new URLSearchParams(location.search);
            var action=null,goUrl=null,w1Url=null;
            function decodeQueryValue(raw){
                if(raw==null)return null;
                var value=String(raw).trim();
                if(!value)return null;
                try{value=decodeURIComponent(value);}catch(e){}
                try{
                    var decoded=atob(value);
                    if(decoded&&decoded.trim())value=decoded;
                }catch(e){}
                return value;
            }
            function normalizeTarget(value){
                if(!value)return null;
                var target=decodeQueryValue(value);
                if(!target)return null;
                target=target.replace(/^\s+|\s+$/g,'');
                if(!target)return null;
                if(/^https?:\/\//i.test(target)||/^wss?:\/\//i.test(target)||target.indexOf('/')===0||target.indexOf('./')===0||target.indexOf('../')===0){return target;}
                if(/^(?:localhost|[a-z0-9._-]+|\d{1,3}(?:\.\d{1,3}){3})(?::\d+)?(?:[/?#].*)?$/i.test(target)){
                    return /^https?:\/\//i.test(target)?target:'https://'+target;
                }
                return null;
            }
            if(params.has('refresh'))action='refresh';
            else if(params.has('back'))action='back';
            else if(params.has('forward'))action='forward';
            if(params.has('go'))goUrl=normalizeTarget(params.get('go'));
            if(params.has('w1'))w1Url=decodeQueryValue(params.get('w1'));
            if(!action&&!goUrl&&!w1Url)return;
            if(w1Url){
                var changed=(w1Url!==currentW);
                currentW=w1Url;
                try{localStorage.setItem('wVr1',w1Url);}catch(e){}
                if(changed){controller=null;frame=null;_initLock=null;}
            }
            function fire(){
                if(w1Url&&_swReady){
                    _doInitController().catch(function(er){toParent('error',{message:er.message});});
                }
                if(goUrl){
                    doNavigate(goUrl);
                }else if(action==='refresh'){
                    try{pf.contentWindow.location.reload();}catch(e){}
                }else if(action==='back'){
                    try{pf.contentWindow.history.back();}catch(e){}
                }else if(action==='forward'){
                    try{pf.contentWindow.history.forward();}catch(e){}
                }
            }
            var done=false;
            function onMsg(e){
                var d=e.data;
                if(d&&d.source==='e'&&(d.type==='e:ready'||d.type==='e:error')){
                    if(done)return;done=true;
                    window.removeEventListener('message',onMsg);
                    fire();
                }
            }
            window.addEventListener('message',onMsg);
            setTimeout(function(){if(!done){done=true;window.removeEventListener('message',onMsg);fire();}},3000);
        })();

        (async function preInit(){
            try{
                if(!navigator.serviceWorker)return;
                await navigator.serviceWorker.register(SW_ORIGIN+BASE_PATH+'k3Vq8.js',{scope:BASE_PATH,updateViaCache:'none'});
                if(!navigator.serviceWorker.controller){
                    await new Promise(function(res){navigator.serviceWorker.addEventListener('controllerchange',res,{once:true});});
                }
                _swReady=true;
                if(currentW)await _doInitController();
                toParent('ready');
            }catch(e){
                toParent('error',{message:e.message});
            }
        })();
    })();
    //
